5351:     static byte[] characterStatus(long objectId, int level, long experience,
5352:                                   int strength, int constitution, int dexterity,
5353:                                   int charisma, int intelligence, int wisdom,
5354:                                   int currentHp, int currentMp,
5355:                                   int maximumHp, int maximumMp,
5356:                                   int armorClass, int food225, int weight240,
5357:                                   int lawful, int fireResistance,
5358:                                   int waterResistance, int windResistance,
5359:                                   int earthResistance) {
5360:         requireDwordId(objectId, "status object id");
5361:         if (level <= 0 || level > (NumericBreakthrough.levelAbilityEnabled()
5362:                 ? NumericBreakthrough.MAX_LEVEL : 0xFF)
5363:                 || experience < 0 || experience > 0xFFFF_FFFFL) {
5364:             throw new IllegalArgumentException("invalid native character status progress");
5365:         }
5366:         if (NumericBreakthrough.levelAbilityEnabled()) {
5367:             requireBreakthroughAbility(strength, "status strength");
5368:             requireBreakthroughAbility(constitution, "status constitution");
5369:             requireBreakthroughAbility(dexterity, "status dexterity");
5370:             requireBreakthroughAbility(charisma, "status charisma");
5371:             requireBreakthroughAbility(intelligence, "status intelligence");
5372:             requireBreakthroughAbility(wisdom, "status wisdom");
5373:         } else {
5374:             requireByte(strength, "status strength");
5375:             requireByte(constitution, "status constitution");
5376:             requireByte(dexterity, "status dexterity");
5377:             requireByte(charisma, "status charisma");
5378:             requireByte(intelligence, "status intelligence");
5379:             requireByte(wisdom, "status wisdom");
5380:         }
5381:         if (NumericBreakthrough.enabled()) {
5382:             requireBreakthroughVital(currentHp, maximumHp, "status HP");
5383:             requireBreakthroughVital(currentMp, maximumMp, "status MP");
5384:             if (armorClass < NumericBreakthrough.MIN_ARMOR_CLASS
5385:                     || armorClass > NumericBreakthrough.MAX_ARMOR_CLASS) {
5386:                 throw new IllegalArgumentException("status armor class exceeds breakthrough range");
5387:             }
5388:         } else {
5389:             requireUnsignedWord(currentHp, "status current HP");
5390:             requireUnsignedWord(currentMp, "status current MP");
5391:             requireUnsignedWord(maximumHp, "status maximum HP");
5392:             requireUnsignedWord(maximumMp, "status maximum MP");
5393:             requireSignedByte(armorClass, "status armor class");
5394:         }
5395:         requireSignedWord(lawful, "status lawful");
5396:         if (NumericBreakthrough.elementalResistanceEnabled()) {
5397:             requireBreakthroughElementalResistance(fireResistance,
5398:                     "status fire resistance");
5399:             requireBreakthroughElementalResistance(waterResistance,
5400:                     "status water resistance");
5401:             requireBreakthroughElementalResistance(windResistance,
5402:                     "status wind resistance");
5403:             requireBreakthroughElementalResistance(earthResistance,
5404:                     "status earth resistance");
5405:         } else {
5406:             requireSignedByte(fireResistance, "status fire resistance");
5407:             requireSignedByte(waterResistance, "status water resistance");
5408:             requireSignedByte(windResistance, "status wind resistance");
5409:             requireSignedByte(earthResistance, "status earth resistance");
5410:         }
5411:         Writer packet = new Writer().c(S_STATUS)
5412:                 // S_STATUS keeps a saturated byte level as the native shadow.
5413:                 // Schema 2 publishes the full dword level through S_EXP.
5414:                 .d(objectId).c(Math.min(level, 0xFF)).d(experience);
5415:         if (NumericBreakthrough.levelAbilityEnabled()) {
5416:             packet.d(strength).d(intelligence).d(wisdom)
5417:                     .d(dexterity).d(constitution).d(charisma);
5418:         } else {
5419:             packet
5420:                 // sub_4A36F0 destinations 0x8348B0..B5 are the retained
5421:                 // S_OwnCharStatus order: STR, INT, WIS, DEX, CON, CHA.
5422:                 // Keep the public method arguments semantic so callers cannot
5423:                 // accidentally encode the selected client's storage order.
5424:                 .c(strength).c(intelligence).c(wisdom)
5425:                 .c(dexterity).c(constitution).c(charisma);
5426:         }
5427:         if (NumericBreakthrough.enabled()) {
5428:             packet.d(currentHp).d(maximumHp).d(currentMp).d(maximumMp)
5429:                     .d(armorClass);
5430:         } else {
5431:             // The unpatched selected receiver uses the same destination order
5432:             // as retained S_OwnCharStatus: current HP, max HP, current MP,
5433:             // max MP.  Schema 1 widens these same four positions only.
5434:             packet.h(currentHp).h(maximumHp).h(currentMp).h(maximumMp)
5435:                     .c(armorClass);
5436:         }
5437:         // This Tournament client renders both gauges as value * 100 / 29
5438:         // (sub_4CFF40/sub_4CFDE0).  The retained database domains are food225
5439:         // and weight240, so sending either raw value overflows the native bars
5440:         // and can make a perfectly valid character appear corrupt. Saturating
5441:         // projection also keeps an out-of-range legacy row from disconnecting
5442:         // the client during S_STATUS construction.
5443:         packet.d(0).c(nativeFoodGauge(food225))
5444:                 .c(nativeWeightGauge(weight240)).h(lawful);
5445:         if (NumericBreakthrough.elementalResistanceEnabled()) {
5446:             packet.d(Integer.toUnsignedLong(fireResistance))
5447:                     .d(Integer.toUnsignedLong(waterResistance))
5448:                     .d(Integer.toUnsignedLong(windResistance))
5449:                     .d(Integer.toUnsignedLong(earthResistance));
5450:         } else {
5451:             packet.c(fireResistance).c(waterResistance)
5452:                     .c(windResistance).c(earthResistance);
5453:         }
5454:         return packet.bytes();
5455:     }
