5575:     private static int nativeGauge29(int retainedValue, int retainedMaximum) {
5576:         int saturated = Math.max(0, Math.min(retainedMaximum, retainedValue));
5577:         return (saturated * 29 + retainedMaximum / 2) / retainedMaximum;
5578:     }
