3: /** Shared opt-in contract for the LiTo launcher/runtime 32-bit stat patches. */
4: final class NumericBreakthrough {
5:     static final int VITAL_ARMOR_SCHEMA_VERSION = 1;
6:     static final int LEVEL_ABILITY_SCHEMA_VERSION = 2;
7:     static final int MAGIC_MODIFIER_SCHEMA_VERSION = 3;
8:     static final int ELEMENTAL_RESISTANCE_SCHEMA_VERSION = 4;
9:     static final int MAX_VITAL = 999_999;
10:     static final int MIN_ARMOR_CLASS = -999_999;
11:     static final int MAX_ARMOR_CLASS = 999_999;
12:     static final int MAX_LEVEL = 999_999;
13:     static final int MAX_ABILITY = 999_999;
14:     static final int MIN_ABILITY_MODIFIER = -999_999;
15:     static final int MAX_ABILITY_MODIFIER = 999_999;
16:     static final int MIN_MAGIC_MODIFIER = -999_999;
17:     static final int MAX_MAGIC_MODIFIER = 999_999;
18:     static final int MIN_ELEMENTAL_RESISTANCE = -999_999;
19:     static final int MAX_ELEMENTAL_RESISTANCE = 999_999;
20:     private static final String ENVIRONMENT = "LITO_NUMERIC_BREAKTHROUGH";
21:     private static final String PROPERTY = "lito.numeric.breakthrough";
22: 
23:     private NumericBreakthrough() {}
24: 
25:     static int schemaVersion() {
26:         String property = System.getProperty(PROPERTY);
27:         String value = property != null ? property : System.getenv(ENVIRONMENT);
28:         if (value == null) return 0;
29:         try {
30:             int parsed = Integer.parseInt(value);
31:             return parsed >= VITAL_ARMOR_SCHEMA_VERSION
32:                     && parsed <= ELEMENTAL_RESISTANCE_SCHEMA_VERSION ? parsed : 0;
33:         } catch (NumberFormatException ignored) {
34:             return 0;
35:         }
36:     }
37: 
38:     static boolean enabled() {
39:         return schemaVersion() >= VITAL_ARMOR_SCHEMA_VERSION;
40:     }
41: 
42:     static boolean levelAbilityEnabled() {
43:         return schemaVersion() >= LEVEL_ABILITY_SCHEMA_VERSION;
44:     }
45: 
46:     static boolean magicModifierEnabled() {
47:         return schemaVersion() >= MAGIC_MODIFIER_SCHEMA_VERSION;
48:     }
